CREATE TABLE IF NOT EXISTS public.articles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL, content text NOT NULL DEFAULT '', summary text NOT NULL DEFAULT '', title_it text, content_it text, summary_it text, is_published boolean NOT NULL DEFAULT false, published_at timestamp with time zone NOT NULL DEFAULT now(), created_at timestamp with time zone NOT NULL DEFAULT now(), updated_at timestamp with time zone NOT NULL DEFAULT now()); ALTER TABLE public.articles ENABLE ROW LEVEL SECURITY; CREATE POLICY "Anyone can view published articles" ON public.articles FOR SELECT USING (is_published = true); CREATE POLICY "Admins can manage articles" ON public.articles FOR ALL TO authenticated USING (public.has_role(auth.uid(), 'admin')) WITH CHECK (public.has_role(auth.uid(), 'admin'));